var rig=UnityEngine.Object.FindObjectOfType<Character.Control.PaddleCharacterVisual>();rig.Pose();
var scene=UnityEngine.SceneManagement.SceneManager.CreateScene("Isolated paddle collider checks",new UnityEngine.SceneManagement.CreateSceneParameters(UnityEngine.SceneManagement.LocalPhysicsMode.Physics2D));
var physics=scene.GetPhysicsScene2D();
UnityEngine.GameObject Obj(string name,UnityEngine.Vector3 pos){var g=new UnityEngine.GameObject(name);UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(g,scene);g.transform.position=pos;return g;}
UnityEngine.PolygonCollider2D Copy(UnityEngine.PolygonCollider2D source,UnityEngine.GameObject dest,UnityEngine.Vector3 origin){var c=dest.AddComponent<UnityEngine.PolygonCollider2D>();c.pathCount=source.pathCount;for(int i=0;i<c.pathCount;i++)c.SetPath(i,source.GetPath(i).Select(v=>(UnityEngine.Vector2)(source.transform.TransformPoint(v+source.offset)-origin)).ToArray());return c;}
try{
 var ground=Obj("Test floor",new UnityEngine.Vector3(0,-3,0));ground.AddComponent<UnityEngine.BoxCollider2D>().size=new UnityEngine.Vector2(30,.4f);
 var body=Obj("Body physical clone",new UnityEngine.Vector3(-3,0,0));var br=body.AddComponent<UnityEngine.Rigidbody2D>();br.constraints=UnityEngine.RigidbodyConstraints2D.FreezeRotation;foreach(var c in rig.body.GetComponentsInChildren<UnityEngine.PolygonCollider2D>())Copy(c,body,rig.body.position);
 var paddle=Obj("Paddle physical clone",new UnityEngine.Vector3(3,0,0));var pr=paddle.AddComponent<UnityEngine.Rigidbody2D>();pr.constraints=UnityEngine.RigidbodyConstraints2D.FreezeRotation;var pc=Copy(rig.tool.Find("Shape").GetComponent<UnityEngine.PolygonCollider2D>(),paddle,rig.tool.position);
 UnityEngine.Physics2D.SyncTransforms();for(int i=0;i<150;i++)physics.Simulate(.02f);
 float bodyBottom=body.GetComponents<UnityEngine.PolygonCollider2D>().Min(c=>c.bounds.min.y);float bladeBottom=pc.bounds.min.y;
 if(UnityEngine.Mathf.Abs(bodyBottom+2.8f)>.04f||UnityEngine.Mathf.Abs(bladeBottom+2.8f)>.04f)throw new System.Exception("Floor support failed "+bodyBottom+" / "+bladeBottom);
 var holder=Obj("Blade contact trigger",new UnityEngine.Vector3(7,0,0));var hr=holder.AddComponent<UnityEngine.Rigidbody2D>();hr.constraints=UnityEngine.RigidbodyConstraints2D.FreezeAll;hr.gravityScale=0;
 var child=Obj("Blade detector",holder.transform.position+rig.tip.position-rig.tool.position);child.transform.rotation=rig.tip.rotation;child.transform.localScale=rig.tip.lossyScale;child.transform.SetParent(holder.transform,true);
 var src=rig.tip.GetComponent<UnityEngine.CapsuleCollider2D>();var tc=child.AddComponent<UnityEngine.CapsuleCollider2D>();tc.size=src.size;tc.offset=src.offset;tc.direction=src.direction;tc.isTrigger=true;
 int enters=0,exits=0;var detector=child.AddComponent<Character.Control.CollisionDetection>();detector.OnCollisionEnter+=()=>enters++;detector.OnCollisionExit+=()=>exits++;
 var probe=Obj("Static terrain probe",child.transform.TransformPoint(tc.offset));probe.AddComponent<UnityEngine.BoxCollider2D>().size=UnityEngine.Vector2.one*.08f;
 UnityEngine.Physics2D.SyncTransforms();for(int i=0;i<4;i++)physics.Simulate(.02f);
 probe.transform.position+=UnityEngine.Vector3.up*5;UnityEngine.Physics2D.SyncTransforms();for(int i=0;i<4;i++)physics.Simulate(.02f);
 if(enters!=1||exits!=1)throw new System.Exception("Blade detection failed "+enters+" / "+exits);
 var shaft=PaddlePixel(new UnityEngine.Vector2(23,90));
 UnityEngine.Vector3 PaddlePixel(UnityEngine.Vector2 pixel){return holder.transform.position+Character.Control.PaddleCharacterVisual.PixelPosition(rig.paddle,pixel)-rig.tool.position;}
 if(tc.OverlapPoint(shaft))throw new System.Exception("Shaft incorrectly activates blade detector");
 string log="PASS isolated actual Physics2D floor drop: body bottom="+bodyBottom+", paddle bottom="+bladeBottom+" (floor=-2.8). Blade enter/exit="+enters+"/"+exits+". Shaft excluded from blade trigger. No gameplay components or saves cloned.";
 System.IO.File.WriteAllText("scripts/player-colliders-20261111/physics.txt",log);UnityEngine.Debug.Log(log);
}finally{UnityEngine.SceneManagement.SceneManager.UnloadSceneAsync(scene);}
